private string[] GetLibs(string libPath)
{
	TextReader textReader = null;
	string text = null;
	try
	{
		textReader = File.OpenText(libPath);
		text = textReader.ReadToEnd();
	}
	catch (Exception ex)
	{
		throw new Exception("加载动态库配置文件异常:" + ex.Message + "\r\n配置文件:" + libPath);
