					return;
				}
				int errorCode = 0;
				LogHelper.Info("GlobalScript execute once start");
				if (!UserGlobalScriptSupport.GetScriptInstance().CodeRun(ref errorCode))
				{
					LogHelper.Error("GlobalScript execute faild " + errorCode);
					if ((long)errorCode != 0)
					{
