	DirectoryInfo directoryInfo = new DirectoryInfo(toolBoxItemData.DirPath);
	DirectoryInfo[] directories = directoryInfo.GetDirectories();
	ItemData itemData = (toolBoxItemData.Items as List<ItemData>).FirstOrDefault();
	if (itemData == null)
	{
