			HikMessageBox.Show(AppLocalizationService.GetLang("Lang_StartErr"), ErrorCodeInfo.GetErrorInfo(vmException.errorCode), MessageIcons.Error);
		}
		DeInitExit();
	}
	else
	{
		LogHelper.objLog.Error("启动失败:" + ex.ToString());
