public virtual byte[] this[string key]
{
	get
	{
		if (!Parent.IsActive || Parent.IsOnDispose)
		{
			return null;
		}
		try
		{
			LogHelper.Info($"获取userdata模块ID名为{Parent.ID} {Parent.Name},key为{key}");
			return GetUIParamValue(key);
		}
		catch (VmException ex)
		{
			LogHelper.Error(ex.errorMessage);
			throw ex;
		}
		catch (Exception ex2)
		{
			LogHelper.Error(ex2.Message);
			throw VmSolution.GetVmException(ex2);
		}
	}
	set
	{
		if (Parent == null || Parent.IsOnDispose)
		{
			return;
		}
		if (Parent.IsGlobalModu || key == "CheckedImages" || key == "DESIGNERBUFFER" || key == "ConfigAvailable")
		{
			SetUIParamValue(key, value);
		}
		else if (Parent.IsDynamicModu)
		{
			IUnRedoService unRedoService = Ioc.Get<IUnRedoService>();
			if (unRedoService != null && unRedoService.ValiteType("ModifyConfig"))
			{
				RecordAllUserData();
				SetUIParamValue(key, value);
				return;
			}
			IUnRedoService unRedoService2 = Ioc.Get<IUnRedoService>();
			if (unRedoService2 == null || !unRedoService2.ValiteType("DeleteModule"))
			{
				IUnRedoService unRedoService3 = Ioc.Get<IUnRedoService>();
				if (unRedoService3 == null || !unRedoService3.ValiteType("CopyModule"))
				{
					if (key.Contains("DynamicIO"))
					{
						SetUIParamValue(key, value);
						return;
					}
					byte[] uIParamValue = GetUIParamValue(key);
					SetUIParamValue(key, value);
					RecordSingleData(uIParamValue, value, key);
					return;
				}
			}
			if (key.Contains("SourceIndex") || key.Contains("TargetIndex") || key.Contains("Position"))
			{
				byte[] uIParamValue2 = GetUIParamValue(key);
				RecordSingleData(uIParamValue2, value, key);
			}
			else
			{
				RecordAllUserData();
			}
			SetUIParamValue(key, value);
		}
		else
		{
			byte[] uIParamValue3 = GetUIParamValue(key);
			SetUIParamValue(key, value);
			if (uIParamValue3 != value && (!(key == "CheckItemParamReady") || (uIParamValue3 != null && (uIParamValue3 == null || value == null || !(Hik.Util.StringUtil.UTF8GetString(uIParamValue3) == Hik.Util.StringUtil.UTF8GetString(value))))))
			{
				RecordSingleData(uIParamValue3, value, key);
			}
		}
	}
}

