public void GetAllModule(List<VmModule> allModules)
{
	foreach (VmModule module in Modules)
	{
		if (module is VmModuleSet)
		{
			allModules.Add(module);
			(module as VmModuleSet).GetAllModule(allModules);
		}
		else
		{
			allModules.Add(module);
