	VmSolution.Instance.AllModules.TryGetValue(proInfo.nNodeID, out var value);
	if (value == null)
	{
		lock (syncObject)
		{
			VmSolution.Instance.AllModules.TryGetValue(proInfo.nNodeID, out value);
			if (value == null)
			{
				Ioc.Get<IUnRedoService>()?.SetForbidRecord(isForbid: true);
				value = CreatModuleByInfo(proInfo);
				value.PreAddModuleTo(this);
				_preGenerateModules.Add(value.ID, value);
				Ioc.Get<IUnRedoService>()?.SetForbidRecord(isForbid: false);
			}
		}
	}
	if (index == 0)
	{
		return value;
	}
	return (value as VmModuleSet).CreateLinkModule(moduleInfo, index - 1);
}

