private object GetItems(ref object source)
{
	if (source == null)
	{
		LoadData();
	}
	if (source == null)
	{
		List<IGrouping<string, GlobalToolDataItem>> list = (from p in toolControlItemData.GetAllChildren().OfType<GlobalToolDataItem>()
			where p.ToolGroupItemInfo != null
			group p by p.ToolGroupItemInfo.groupName).ToList();
		list.Sort((IGrouping<string, GlobalToolDataItem> p1, IGrouping<string, GlobalToolDataItem> p2) => string.Compare(p1.Key, p2.Key));
		List<List<GlobalToolDataItem>> list2 = list.Select((IGrouping<string, GlobalToolDataItem> p) => p.ToList()).ToList();
		list2.ForEach((List<GlobalToolDataItem> p) =>
		{
			p.Sort((GlobalToolDataItem globalToolDataItem, GlobalToolDataItem globalToolDataItem2) => (globalToolDataItem.ToolGroupItemInfo.Priority > globalToolDataItem2.ToolGroupItemInfo.Priority) ? 1 : (-1));
		});
		List<GlobalToolDataItem> source2 = list2.SelectMany((List<GlobalToolDataItem> p) => p.ToArray()).ToList();
		objItems = source2.Where((GlobalToolDataItem p) => p.IsShowExternal).ToList();
		source = objItems;
	}
	return source;
}

