			ImvsSdkDefine.IMVS_REPORT_MODULE_STATUS_INFO_LIST valueOrDefault2 = iMVS_REPORT_MODULE_STATUS_INFO_LIST2.GetValueOrDefault();
			if (iMVS_REPORT_MODULE_STATUS_INFO_LIST2.HasValue)
			{
				ImvsSdkDefine.IMVS_REPORT_MODULE_STATUS_INFO[] pstModuleStatuInfo = valueOrDefault2.pstModuleStatuInfo;
				for (int num = 0; num < valueOrDefault2.nNum; num++)
				{
					ImvsSdkDefine.IMVS_REPORT_MODULE_STATUS_INFO moduleState = pstModuleStatuInfo[num];
					vmModuleCollection[num].SetModuleState(moduleState);
				}
			}
		}
		Modules = vmModuleCollection;
	}
	catch (VmException ex2)
	{
		string text2 = AppLocalizationService.GetLang("errCode:") + $"{ex2.errorCode:X}" + "\r\n";
		text2 = text2 + AppLocalizationService.GetLang("errInfo:") + ErrorCodeInfo.GetErrorInfo(ex2.errorCode);
